export function getIconForLanguageExtension(
  language: string,
  props?: React.HTMLAttributes<SVGElement>
) {
  switch (language) {
    case "json":
      return <Icons.json {...props} />;
    case "css":
      return <Icons.css {...props} />;
    case "vue":
      return <Icons.vue {...props} />;
    case "svelte":
      return <Icons.svelte {...props} />;
    case "html":
      return <Icons.html {...props} />;
    case "bash":
    case "sh":
    case "shell":
      return <Icons.bash {...props} />;
    case "js":
      return <Icons.javascript {...props} />;
    // A file of JSX is a React component.
    case "jsx":
    case "tsx":
      return <Icons.reactColor {...props} />;
    case "ts":
    case "typescript":
      return <Icons.ts {...props} />;
    default:
      return <FileIcon {...(props as any)} />;
  }
}
